import { getCurrentLanguage, translateElement, translatePath } from "./i18n.js?v=2.57";
import { loadGameData } from "./game-data.js?v=1";

// Generated by scripts/sync-data.mjs; edit scripts/data/overrides.json, not this data.
export const AVATAR_METADATA = await loadGameData('avatars.json');

export const CW_ROLE_METADATA = {
  "6042": {
    "names": {
      "th": "King Pom-Pom",
      "en": "King Pom-Pom",
      "zh-CN": "帕姆大王",
      "zh-TW": "帕姆大王",
      "ja": "パム大王",
      "ko": "폼폼 대왕"
    },
    "path": "Elation",
    "element": "Physical",
    "rarity": 5,
    "hasExRank": false
  }
};

// Localized defaults used when a Trailblazer entry stores the {NICKNAME} placeholder.
const TRAILBLAZER_DEFAULT_NAMES = {
  th: 'ผู้บุกเบิก (Trailblazer)',
  en: 'Trailblazer',
  'zh-CN': '开拓者',
  'zh-TW': '開拓者',
  ja: '開拓者',
  ko: '개척자',
  ru: 'Первопроходец',
  vi: 'Nhà Khai Phá',
  id: 'Trailblazer',
  es: 'El Emisario',
  fr: 'Le Pionnier',
  de: 'Der Bahnbrecher',
  pt: 'O Desbravador'
};

export function getAvatarInfo(avatarId, langOverride = null) {
  const lang = langOverride || getCurrentLanguage();
  const meta = AVATAR_METADATA[avatarId] || CW_ROLE_METADATA[avatarId];

  if (!meta) {
    return {
      name: `Avatar ${avatarId}`,
      path: translatePath("Unknown"),
      element: translateElement("Unknown"),
      rarity: 4,
      hasExRank: false
    };
  }

  let localizedName = meta.names?.[lang] || meta.names?.en || meta.names?.th || `Avatar ${avatarId}`;
  if (localizedName.includes('{NICKNAME}')) {
    const tbName = TRAILBLAZER_DEFAULT_NAMES[lang] || TRAILBLAZER_DEFAULT_NAMES.en;
    localizedName = localizedName.replace(/\{NICKNAME\}/g, tbName).trim();
    if (!localizedName) localizedName = tbName;
  }

  return {
    name: localizedName,
    path: translatePath(meta.path),
    element: translateElement(meta.element),
    rawPath: meta.path,
    rawElement: meta.element,
    rarity: meta.rarity,
    hasExRank: !!meta.hasExRank
  };
}
